(() => {
  // Find the element containing the standard model ID "river-flash-5898"
  const all = document.querySelectorAll('*');
  let target = null;
  for (const el of all) {
    if (el.children.length === 0 && el.textContent.trim() === 'river-flash-5898') {
      target = el;
      break;
    }
  }
  if (!target) return { found: false };
  // Build a unique CSS selector path
  const path = [];
  let cur = target;
  while (cur && cur !== document.body) {
    let sel = cur.tagName.toLowerCase();
    if (cur.id) { sel = '#' + cur.id; path.unshift(sel); break; }
    if (cur.className && typeof cur.className === 'string') {
      sel += '.' + cur.className.trim().split(/\s+/).join('.');
    }
    const parent = cur.parentElement;
    if (parent) {
      const siblings = Array.from(parent.children).filter(c => c.tagName === cur.tagName);
      if (siblings.length > 1) {
        const idx = siblings.indexOf(cur) + 1;
        sel += `:nth-of-type(${idx})`;
      }
    }
    path.unshift(sel);
    cur = cur.parentElement;
  }
  return { found: true, selector: path.join(' > '), tag: target.tagName, text: target.textContent };
})()
